#!/bin/sh
# Writes Formula/sapu.rb for the depapp/homebrew-tap repo from a release version and its SHA256SUMS.
# Usage: scripts/brew-formula.sh 0.2.0 path/to/SHA256SUMS > ../homebrew-tap/Formula/sapu.rb
set -e
version=$1; sums=$2
[ -n "$version" ] && [ -f "$sums" ] || { echo "usage: $0 <version> <SHA256SUMS>" >&2; exit 1; }
hash() { awk -v f="$1" '$2 == f { print $1 }' "$sums"; }
base="https://github.com/depapp/sapu/releases/download/v$version"
cat <<RUBY
# Generated by scripts/brew-formula.sh on release; do not edit by hand.
class Sapu < Formula
  desc "Sweep your Android clean: deep clean, debloat, analyze and optimize over adb, no root"
  homepage "https://github.com/depapp/sapu"
  version "$version"
  license "GPL-3.0-only"

  on_macos do
    on_arm do
      url "$base/sapu-darwin-arm64"
      sha256 "$(hash sapu-darwin-arm64)"
    end
    on_intel do
      url "$base/sapu-darwin-amd64"
      sha256 "$(hash sapu-darwin-amd64)"
    end
  end

  on_linux do
    on_arm do
      url "$base/sapu-linux-arm64"
      sha256 "$(hash sapu-linux-arm64)"
    end
    on_intel do
      url "$base/sapu-linux-amd64"
      sha256 "$(hash sapu-linux-amd64)"
    end
  end

  depends_on "android-platform-tools" => :recommended

  def install
    bin.install Dir["sapu-*"].first => "sapu"
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/sapu --version")
  end
end
RUBY
